83	        types: RemoveBooleanFromPropertiesOnEach<
84	          DeepRequired<
85	            RemoveBooleanFromProperties<
86	              DeepRequired<
87	                NxJsonConfiguration['release']['conventionalCommits']['types']
88	              >,
89	              string
90	            >
91	          >,
92	          'changelog'
93	        >;
94	      };
95	    }
96	  >,
97	  // projects is just a shorthand for the default group's projects configuration, it does not exist in the final config
98	  'projects'
99	>;
