/**
 * Determine whether the user has enabled the creation of a GitHub release anywhere in their
 * changelog configuration (either at the workspace level, the project level, or within any
 * release group).
 */
function hasCreateReleaseEnabled(
  userConfig: NxJsonConfiguration['release']
): boolean {
  const isCreateReleaseEnabled = (
    changelogConfig:
      | boolean
      | NxReleaseChangelogConfiguration
      | undefined
      | null
  ): boolean => {
    return (
      !!changelogConfig &&
      typeof changelogConfig !== 'boolean' &&
      !!changelogConfig.createRelease
    );
  };

  if (
    isCreateReleaseEnabled(userConfig.changelog?.workspaceChangelog) ||
    isCreateReleaseEnabled(userConfig.changelog?.projectChangelogs)
  ) {
    return true;
  }

  if (userConfig.groups) {
    for (const group of Object.values(userConfig.groups)) {
      if (isCreateReleaseEnabled(group.changelog)) {
        return true;
      }
    }
  }

  return false;
